-- @AuditorSistema V1.0 — initial adapters
on conflict(system_id) do update set display_name=excluded.display_name,adapter_version=excluded.adapter_version,target_project_id=excluded.target_project_id,target_namespace=excluded.target_namespace,authority=excluded.authority,drive_root_id=excluded.drive_root_id,notion_page_id=excluded.notion_page_id,active=true,updated_at=now();

-- NRFiPrensa required checks
on conflict(system_id,check_id) do update set layer_id=excluded.layer_id,title=excluded.title,rule_text=excluded.rule_text,default_severity=excluded.default_severity,required=excluded.required,target_objects=excluded.target_objects;

-- NRFImetrica required checks
on conflict(system_id,check_id) do update set layer_id=excluded.layer_id,title=excluded.title,rule_text=excluded.rule_text,default_severity=excluded.default_severity,required=excluded.required,target_objects=excluded.target_objects;
